import {defaults,solve,validate} from './models.js';
const $=id=>document.getElementById(id);
const meta={
 '1':{name:'Dependence & bargaining',title:'The price of dependence',description:'Competition can lower the first bid while proprietary dependence raises the price of future amendments.',knobs:[['m','Monitoring probability',0,1,.01,'How often a failure is detected and enforced.'],['p','Portability requirements',0,5,.05,'Stronger portability weakens proprietary dependence.']],metrics:[['effort','Quality effort','effort units'],['dependence','Proprietary dependence','dependence units'],['agency_gross_payment','Lifecycle payments','cost units']],assumptions:['Initial bids are fully competitive and unrestricted, including negative bids.','Switching cost is s₀ + αk/(1+p); the global continuation condition must hold.','Agency value excludes penalty receipts. Social welfare treats penalties as transfers.'],read:(p,r)=>`Quality effort is ${fmt(r.effort)} and dependence is ${fmt(r.dependence)}. The initial bid is ${fmt(r.initial_price)}; the amendment price is ${fmt(r.amendment_price)}. Expected total vendor profit is zero under fully informed competition.`,warning:r=>r.negative_initial_bid?'This scenario requires a negative initial bid. A nonnegative bid constraint would require a different equilibrium.':'A positive amendment margin is not the same as excess total profit.'},
 '2':{name:'Paid remediation',title:'When repair becomes revenue',description:'Explore how warranty enforcement and paid repair margins change a vendor’s incentive to prevent defects.',knobs:[['w','Warranty enforcement',0,1,.01,'Probability a defect triggers an enforceable warranty.'],['mu','Paid repair margin',0,15,.1,'Vendor margin on a repair billed as additional work.']],metrics:[['effort','Prevention effort','effort units'],['defect_probability','Defect probability','probability'],['welfare_loss','Excess social cost','cost units']],assumptions:['All defects are repaired; uncovered repairs earn the specified net margin.','Effort reduces defect probability exponentially; prevention has quadratic cost.','Total social loss H includes repair and harm; fixed award payments are omitted.'],read:(p,r)=>`The vendor chooses ${fmt(r.effort)} units of prevention, compared with a public optimum of ${fmt(r.public_effort)}. Positive prevention requires warranty enforcement above ${pct(p.mu/(p.mu+p.r+p.f)||0)}.`,warning:()=> 'Reduced prevention is an incentive result, not evidence of sabotage or deception.'},
 '3':{name:'Metered workflows',title:'Paying for activity or outcomes',description:'Compare usage payments with verified-outcome bonuses, including their effects on work, completion, and public burden.',knobs:[['t','Payment per action',0,10,.1,'Marginal payment for checks, retries, or tool calls.'],['R','Verified-outcome bonus',0,30,.5,'Payment for correct, independently verified completion.']],metrics:[['work','Workflow intensity','work units'],['success','Verified completion','probability'],['welfare_loss','Welfare loss','value units']],assumptions:['Work is discretionary and continuous; legally required actions are outside the choice.','Success is 1−exp(−an), and workflow intensity cannot exceed cap.','Welfare counts vendor processing costs and external burden; fixed fees are omitted.'],read:(p,r)=>`The vendor chooses ${fmt(r.work)} work units; the public optimum is ${fmt(r.public_work)}. This is ${Math.abs(r.work_gap)<1e-7?'aligned with':r.work_gap>0?'above':'below'} the efficient workload. Completion probability is ${pct(r.success)}.`,warning:()=> 'A fixed fee without outcome incentives can create too little work; usage payment can create too much.'},
 '4':{name:'Rewarded flags',title:'What gets flagged gets paid',description:'See how per-flag rewards and false-positive enforcement change the threshold for flagging a case.',knobs:[['t','Reward per flag',0,15,.1,'Payment for flagging, independent of whether the flag is correct.'],['m','Enforcement probability',0,1,.01,'Probability a false flag leads to an enforceable penalty.']],metrics:[['threshold','Flagging threshold','probability'],['false_positive_mass','False flags per case','population share'],['welfare_loss','Welfare loss','value units']],assumptions:['Calibrated risk scores are uniform on [0,1]; error prevalence is 50%.','Payment errors are not assumed to be intentional fraud.','At zero enforcement and reward equal to processing cost, the vendor selects no flags.'],read:(p,r)=>`The vendor flags above ${pct(r.threshold)} estimated error risk; the public threshold is ${pct(r.public_threshold)}. False flags affect ${pct(r.false_positive_mass)} of all cases, versus a false-positive rate of ${pct(r.false_positive_rate)} among cases without errors.`,warning:()=> 'The uniform risk-score distribution is illustrative, not an observed applicant population.'},
 '5':{name:'Shared validation',title:'Who pays to check the system?',description:'Explore the collective-action problem when every agency benefits from a test funded by just one buyer.',knobs:[['N','Participating agencies',2,50,1,'Agencies sharing the benefit of common validation.'],['c','Cost of validation',.01,3,.01,'Cost incurred by an agency that volunteers to test.']],metrics:[['no_test_probability','No validation','probability'],['expected_tests','Expected tests','tests'],['total_welfare_loss','Welfare loss (shared + local)','value units']],assumptions:['A single shared test is sufficient, and agencies choose simultaneously.','The selected equilibrium is symmetric mixed when c < B; otherwise it is no testing.','One-tester pure equilibria also exist when c ≤ B. Coordination is a benchmark, not a prediction.','Each agency separately decides a local test with no spillovers; it values only ω of the local benefit and tests at indifference.'],read:(p,r)=>`The selected ${r.symmetric_equilibrium==='mixed'?'mixed':'no-testing'} equilibrium leaves a ${pct(r.no_test_probability)} probability of no validation. Coordinated welfare is ${fmt(r.coordinated_welfare)}, compared with ${fmt(r.selected_welfare)} under the selected equilibrium.`,warning:r=>r.equality_boundary?'At c = B, no testing is selected, but additional weak equilibria exist.':r.local_test_public&&!r.local_test?`Local validation is omitted even though it is socially worthwhile, adding ${fmt(r.local_welfare_loss)} in welfare loss across agencies.`:'Free riding concerns common tests; local suitability is a separate, unshared decision.'},
 '6':{name:'Human review',title:'The hidden labor of automation',description:'See when government review protects applicants but weakens the vendor’s incentive to prevent errors.',knobs:[['h','Agency review cost',.1,70,.1,'Real staff resources required to review the output.'],['c','High-effort cost',.1,20,.1,'Vendor cost of delivering the lower error rate.']],metrics:[['high_effort','High vendor effort','binary'],['agency_review_cost','Agency review labor','cost units'],['welfare_loss','Excess social cost','cost units']],assumptions:['The agency observes quality and chooses review after vendor effort; review catches every error.','Only uncorrected errors trigger penalties, which the agency receives.','At indifference, the agency skips review and the vendor selects low effort.'],read:(p,r)=>`The vendor selects ${r.high_effort?'high':'low'} effort, and the agency ${r.review?'reviews the output':'does not review'}. Raw error probability is ${pct(r.raw_error)}, but final error probability is ${pct(r.final_error)}. The public optimum costs ${fmt(r.public_social_cost)} versus ${fmt(r.social_cost)} in equilibrium.`,warning:()=> 'Few final errors can coexist with substantial public review labor. Review is not inherently wasteful.'},
 '7':{name:'Post-award substitution',title:'Can the promise be enforced?',description:'Test whether audits and credible remedies deter a supplier from replacing an accepted configuration with a cheaper one.',knobs:[['rho','Termination credibility',0,1,.01,'Fraction of threatened future margin genuinely at risk.'],['H','Public harm from substitution',0,20,.1,'Expected public harm before subtracting real cost savings.']],metrics:[['selected_audit','Selected audit probability','probability'],['substitutes','Cheaper substitution','binary'],['policy_welfare_loss','Audit-policy welfare loss','value units']],assumptions:['The vendor retains quality at indifference; the agency tolerates substitution at policy indifference.','Audits deter through sanctions and do not reverse harm; the agency retains no sanctions.','The social benchmark is the best feasible audit policy, accounting for real cost savings.'],read:(p,r)=>`${r.deterrence_feasible?`Deterrence requires an audit probability of at least ${pct(r.minimum_audit)}.`:'Available remedies cannot deter substitution even with certain auditing.'} The agency ${r.substitutes?'tolerates substitution':'deters substitution'}. Net social cost is ${fmt(r.social_cost)}.`,warning:()=> 'A cheaper configuration can improve social welfare if real savings exceed harm. Negative social cost can be meaningful.'},
 '8':{name:'Lock-in & remediation',title:'When dependence prices the repair',description:'Combine Models 1 and 2: uncovered defects become amendments, and their price rises with the incumbent’s lock-in.',knobs:[['p','Portability requirements',0,5,.05,'Lowers switching costs and the return to proprietary dependence.'],['w','Warranty enforcement',0,1,.01,'Probability a defect is classified and enforced as a covered repair.']],metrics:[['effort','Prevention effort','effort units'],['dependence','Proprietary dependence','dependence units'],['welfare_loss','Excess social cost','cost units']],assumptions:['The vendor chooses prevention and dependence jointly; dependence raises the bargained margin on uncovered repairs and on exogenous new work.','Initial bids are fully competitive, so expected profit is zero; distortions in effort and dependence remain.','Social cost counts prevention, dependence, new-work cost and defect harm H; penalties are transfers.'],read:(p,r)=>`Dependence of ${fmt(r.dependence)} makes an uncovered repair worth a margin of ${fmt(r.repair_margin)} to the vendor, so prevention effort is ${fmt(r.effort)} (planner: ${fmt(r.public_effort)}) and defects occur with probability ${pct(r.defect_probability)}.`,warning:r=>r.negative_initial_bid?'Anticipated continuation revenue implies a negative competitive initial bid; no bid floor is imposed.':'Portability now raises prevention as well as lowering amendment prices, an interaction absent from either standalone model.'},
 '9':{name:'Metered work & review',title:'Who finishes the job?',description:'Combine Models 3 and 6: the vendor chooses billable work, then the agency decides whether staff must review and correct the output.',knobs:[['t','Payment per action',0,10,.1,'Marginal payment for checks, retries or tool calls.'],['f','Penalty per uncorrected error',0,19.5,.1,'Paid by the vendor only for errors that reach applicants.']],metrics:[['work','Workflow intensity','work units'],['agency_review_cost','Agency review cost','cost units'],['welfare_loss','Excess social cost','cost units']],assumptions:['The agency observes the raw error rate and reviews when screening plus correction is cheaper than its net loss; it reviews at indifference.','Review costs h plus κ per corrected error and removes all errors before harm.','The planner chooses work and review jointly; penalties are transfers.'],read:(p,r)=>`The vendor performs ${fmt(r.work)} units of work, leaving a raw error rate of ${pct(r.raw_error)}. The agency ${r.review?`reviews, spending ${fmt(r.agency_review_cost)} on staff labor`:'does not review'}; the planner would choose ${fmt(r.public_work)} units ${r.public_review?'with':'without'} review.`,warning:r=>r.review&&r.welfare_loss>1e-9?'Review protects applicants, but the vendor is paid for activity whose errors public staff then correct.':'Penalties apply only to uncorrected errors, so review removes them from the vendor’s calculation.'}
};
const names={F:'Failure penalty',ce:'Quality-effort cost coefficient',ck:'Dependence cost coefficient',lam:'Probability of additional work',theta:'Vendor bargaining weight',alpha:'Effect of dependence on switching',s0:'Baseline switching cost',cR:'Replacement vendor price',cI:'Incumbent additional-work cost',V:'Public value of success',b:'External burden coefficient',omega:'Agency weight on burden',gm:'Monitoring cost coefficient',gp:'Portability cost coefficient',r:'Real repair cost',f:'Enforceable penalty',a:'Productivity of additional work',d:'Quadratic workflow cost',cap:'Maximum workflow intensity',v:'Benefit of correct flag',h:'Harm from false flag',B:'Shared validation benefit',pH:'Error probability with high effort',pL:'Error probability with low effort',L:'Harm per uncorrected error',s:'Savings from substitution',R:'Future vendor margin',k:'Audit cost coefficient',H:'Social loss per defect',c:'Cost coefficient',ell:'Local test cost',Lloc:'Local test benefit',rR:'Replacement repair cost',kappa:'Correction cost per error'};
function fmt(v){if(v===null)return 'Not available';if(typeof v==='boolean')return v?'Yes':'No';if(typeof v==='string')return v;if(Math.abs(v)<1e-10)v=0;return new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(v)}
function pct(v){return `${fmt(v*100)}%`}
function display(v,unit){return unit==='probability'||unit==='population share'?pct(v):unit==='binary'?(v?'Yes':'No'):fmt(v)}
let id='1',params={},reference={},pinned=false,axis='',sweep=[];
const scenarios={};
try{const stored=JSON.parse(localStorage.getItem('procurement-lab-v1')||'{}');for(const [key,v] of Object.entries(stored)){try{validate(key,v.params);validate(key,v.reference);scenarios[key]=v}catch{}}}catch{}
function persist(){scenarios[id]={params:{...params},reference:{...reference},pinned,axis};try{localStorage.setItem('procurement-lab-v1',JSON.stringify(scenarios))}catch{}}
function label(key){const knob=meta[id].knobs.find(k=>k[0]===key);if(knob)return knob[1];if(id==='7'&&key==='d')return 'Audit detection probability';if(id==='5'&&key==='omega')return 'Agency weight on local benefit';if(id==='9'&&key==='h')return 'Review screening cost';if(id==='9'&&key==='R')return 'Verified-correctness bonus';if(id==='8'&&key==='w')return 'Warranty enforcement';return names[key]||key}
function setError(message){$('error').textContent=message;$('error').hidden=!message}
function activate(next){
 id=meta[next]?next:'1';const saved=scenarios[id];params={...defaults[id],...saved?.params};reference={...defaults[id],...saved?.reference};pinned=!!saved?.pinned;axis=meta[id].knobs.some(k=>k[0]===saved?.axis)?saved.axis:meta[id].knobs[0][0];
 document.querySelectorAll('#models button').forEach(b=>b.setAttribute('aria-current',b.dataset.id===id?'page':'false'));
 $('eyebrow').textContent=`MODEL ${id.padStart(2,'0')} / STRATEGIC PROCUREMENT`;$('title').textContent=meta[id].title;$('description').textContent=meta[id].description;
 $('axis').replaceChildren(...meta[id].knobs.map(k=>{const o=document.createElement('option');o.value=k[0];o.textContent=k[1];return o}));$('axis').value=axis;
 $('assumptions').replaceChildren(...meta[id].assumptions.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));
 $('advanced').open=false;setError('');buildControls();render();
}
function buildControls(){
 $('sliders').replaceChildren();
 for(const [key,title,min,max,step,help] of meta[id].knobs){
   const box=document.createElement('div');box.className='slider-group';
   const lab=document.createElement('label');lab.className='slider-label';lab.htmlFor=`control-${key}`;lab.append(document.createTextNode(title));
   const out=document.createElement('output');out.id=`value-${key}`;out.htmlFor=`control-${key}`;out.textContent=fmt(params[key]);lab.append(out);
   const input=document.createElement('input');input.type='range';input.id=`control-${key}`;input.min=Math.min(min,params[key]);input.max=Math.max(max,params[key]);input.step=step;input.value=params[key];
   const range=document.createElement('div');range.className='slider-range';const low=document.createElement('span'),high=document.createElement('span');low.textContent=input.min;high.textContent=input.max;range.append(low,high);
   const hint=document.createElement('p');hint.className='slider-help';hint.textContent=help;
   input.addEventListener('input',()=>{const next={...params,[key]:Number(input.value)};try{validate(id,next);params=next;out.textContent=fmt(params[key]);const field=$('parameters').querySelector(`[name="${key}"]`);field.value=params[key];setError('');persist();render()}catch(e){setError(e.message)}});
   box.append(lab,input,range,hint);$('sliders').append(box);
 }
 $('parameters').replaceChildren(...Object.keys(params).map(key=>{const lab=document.createElement('label');lab.append(document.createTextNode(label(key)));const code=document.createElement('small');code.textContent=key;const input=document.createElement('input');input.type='number';input.name=key;input.value=params[key];input.step=key==='N'?'1':'any';input.min=0;input.max=1e6;input.required=true;lab.append(code,input);return lab}));
}
function makeSweep(){
 const knob=meta[id].knobs.find(k=>k[0]===axis),min=Math.min(knob[2],params[axis],reference[axis]),max=Math.max(knob[3],params[axis],reference[axis]);
 const values=Array.from({length:81},(_,i)=>min+(max-min)*i/80);values.push(params[axis],reference[axis]);
 if(id==='6'&&axis==='h'){for(const p of [params,reference])for(const z of [p.pH*(p.L-p.f),p.pL*(p.L-p.f)]){if(z>=min&&z<=max)values.push(z,Math.max(min,z-1e-6))}}
 const xs=[...new Set(values.map(x=>axis==='N'?Math.round(x):Number(x.toPrecision(12))))].sort((a,b)=>a-b);
 return xs.map(x=>({x,current:solve(id,{...params,[axis]:x}),reference:solve(id,{...reference,[axis]:x})}));
}
function render(){
 const r=solve(id,params),ref=solve(id,reference),spec=meta[id];sweep=makeSweep();
 $('metrics').replaceChildren(...spec.metrics.map(([key,title,unit])=>{const box=document.createElement('div');box.className='metric';const name=document.createElement('div');name.className='metric-label';name.textContent=title;const value=document.createElement('div');value.className='metric-value';value.textContent=display(r[key],unit);const sub=document.createElement('div');sub.className='metric-sub';sub.textContent=`Comparison: ${display(ref[key],unit)} · ${unit==='binary'?'selected state':unit}`;box.append(name,value,sub);return box}));
 $('takeaway').textContent=spec.read(params,r);$('warning').textContent=spec.warning(r);$('comparison-label').textContent=pinned?'Pinned comparison':'Default comparison';
 $('sweep-description').textContent=`Vary ${label(axis).toLowerCase()}; hold other terms fixed for each scenario.`;
 $('chart-detail').textContent='Select or hover over a chart point to inspect a solved scenario.';
 $('outcomes').replaceChildren(...Object.keys(r).map(key=>{const tr=document.createElement('tr');for(const text of [key.replaceAll('_',' '),fmt(r[key]),fmt(ref[key])]){const td=document.createElement('td');td.textContent=text;tr.append(td)}return tr}));
 drawCharts();
}
const ns='http://www.w3.org/2000/svg';
function el(tag,attrs={},text){const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function drawCharts(){
 $('charts').replaceChildren();
 for(const [key,title,unit] of meta[id].metrics){
  const section=document.createElement('div');section.className='chart';const h=document.createElement('h3');h.textContent=title;section.append(h);$('charts').append(section);
  const w=Math.max(section.getBoundingClientRect().width,230),height=245,l=48,r=12,t=18,b=48,pw=w-l-r,ph=height-t-b;
  const svg=el('svg',{viewBox:`0 0 ${w} ${height}`,role:'img','aria-label':`${title} by ${label(axis)}. Current and comparison scenario.`});section.append(svg);
  svg.append(el('title',{},`${title} sensitivity, ${unit}`));
  const xmin=sweep[0].x,xmax=sweep.at(-1).x;
  let ymin=Math.min(...sweep.flatMap(row=>[Number(row.current[key]),Number(row.reference[key])])),ymax=Math.max(...sweep.flatMap(row=>[Number(row.current[key]),Number(row.reference[key])]));
  const pad=(ymax-ymin)*.08||.1;ymin-=pad;ymax+=pad;
  const x=v=>l+4+(v-xmin)/(xmax-xmin||1)*(pw-8),y=v=>t+ph-(Number(v)-ymin)/(ymax-ymin)*ph;
  for(let i=0;i<4;i++){const v=ymin+(ymax-ymin)*i/3,py=y(v);svg.append(el('line',{x1:l,y1:py,x2:w-r,y2:py,stroke:'#e5eae3','stroke-width':1}));svg.append(el('text',{x:l-7,y:py+3,'text-anchor':'end'},Math.abs(v)<1e-7?'0':Number(v.toPrecision(2)).toString()))}
  for(let i=0;i<4;i++){const v=xmin+(xmax-xmin)*i/3;svg.append(el('text',{x:x(v),y:height-b+19,'text-anchor':i===0?'start':i===3?'end':'middle'},Number(v.toPrecision(3)).toString()))}
  svg.append(el('text',{x:l,y:height-5,class:'axis-title'},`${axis} · varied parameter`));
  svg.append(el('text',{x:l,y:10,class:'axis-title'},unit));
  for(const [which,color,dash] of [['reference','#b76b43','5 4'],['current','#183e39','']]){
    const path=sweep.map((row,i)=>`${i?'L':'M'}${x(row.x)},${y(row[which][key])}`).join(' ');
    svg.append(el('path',{d:path,fill:'none',stroke:color,'stroke-width':2,'stroke-dasharray':dash}));
  }
  const current=solve(id,params)[key];svg.append(el('line',{x1:x(params[axis]),x2:x(params[axis]),y1:t,y2:height-b,stroke:'#a4b4aa','stroke-dasharray':'2 4'}));svg.append(el('circle',{cx:x(params[axis]),cy:y(current),r:4.5,fill:'#183e39',stroke:'#fff','stroke-width':2}));
  const guide=el('line',{y1:t,y2:height-b,stroke:'#b76b43',visibility:'hidden'});svg.append(guide);
  const hit=el('rect',{x:l,y:t,width:pw,height:ph,fill:'transparent'});svg.append(hit);
  const inspect=event=>{const box=svg.getBoundingClientRect(),px=(event.clientX-box.left)/box.width*w,value=xmin+(px-l-4)/(pw-8)*(xmax-xmin);let row=sweep.reduce((best,row)=>Math.abs(row.x-value)<Math.abs(best.x-value)?row:best,sweep[0]);guide.setAttribute('x1',x(row.x));guide.setAttribute('x2',x(row.x));guide.setAttribute('visibility','visible');$('chart-detail').textContent=`${label(axis)} = ${fmt(row.x)} · ${title}: current ${display(row.current[key],unit)}, comparison ${display(row.reference[key],unit)} · Solved grid point`;};
  hit.addEventListener('pointermove',inspect);hit.addEventListener('click',inspect);hit.addEventListener('pointerleave',()=>guide.setAttribute('visibility','hidden'));
 }
}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
for(const [key,spec] of Object.entries(meta)){const b=document.createElement('button');b.dataset.id=key;const number=document.createElement('span');number.className='nav-number';number.textContent=key.padStart(2,'0');b.append(number,document.createTextNode(spec.name));b.onclick=()=>{location.hash=`model=${key}`};$('models').append(b)}
$('reset').onclick=()=>{delete scenarios[id];activate(id);persist()};
$('pin').onclick=()=>{reference={...params};pinned=true;persist();render()};
$('axis').onchange=()=>{axis=$('axis').value;persist();render()};
$('parameter-form').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(Array.from(new FormData(e.target).entries(),([k,v])=>[k,Number(v)]));try{validate(id,next);params=next;setError('');buildControls();persist();render()}catch(error){setError(error.message)}};
$('export-json').onclick=()=>download(`procurement-model-${id}.json`,JSON.stringify({model:id,parameters:params,comparison:reference,outcomes:solve(id,params),comparisonOutcomes:solve(id,reference),method:'Deterministic equilibrium; illustrative parameters; browser port verified against Python'},null,2),'application/json');
$('export-csv').onclick=()=>{const rows=sweep.flatMap(row=>['current','reference'].map(scenario=>({model:id,scenario,...(scenario==='current'?params:reference),[axis]:row.x,...row[scenario]})));const columns=Object.keys(rows[0]);const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';download(`procurement-model-${id}-sweep.csv`,[columns.map(quote).join(','),...rows.map(r=>columns.map(k=>quote(r[k])).join(','))].join('\n'),'text/csv')};
window.addEventListener('hashchange',()=>activate(new URLSearchParams(location.hash.slice(1)).get('model')||'1'));
let priorWidth=0;new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-priorWidth)>1){priorWidth=width;if(sweep.length)drawCharts()}}).observe($('charts'));
activate(new URLSearchParams(location.hash.slice(1)).get('model')||'1');
